INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT133-S3-Q3$batch08$, 133, 3, 3, $batch08$Most Supported$batch08$, $batch08$The qwerty keyboard became the standard keyboard with the invention of the typewriter and remains the standard for typing devices today. If an alternative known as the Dvorak keyboard were today's standard, typists would type significantly faster. Nevertheless, it is not practical to switch to the Dvorak keyboard because the cost to society of switching, in terms of time, money, and frustration, would be greater than the benefits that would be ultimately gained from faster typing.$batch08$, $batch08$The example above best illustrates which one of the following propositions?$batch08$, $batch08$E$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=133 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT133-S3-Q3$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$Often it is not worthwhile to move to a process that improves speed if it comes at the expense of accuracy.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT133-S3-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$People usually settle on a standard because that standard is more efficient than any alternatives.$batch08$, $batch08$Opposite$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT133-S3-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$People often remain with an entrenched standard rather than move to a more efficient alternative simply because they dislike change.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT133-S3-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$The emotional cost associated with change is a factor that sometimes outweighs financial considerations.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT133-S3-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$The fact that a standard is already in wide use can be a crucial factor in making it a more practical choice than an alternative.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT133-S3-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT133-S3-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Qwerty became the standard with the typewriter and still is. Dvorak would make typists much faster. But switching isn't practical, because the cost of switching in time, money, and frustration would exceed the benefit.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$The reason qwerty stays isn't that it's better. Dvorak is better. Qwerty stays because everyone already uses it, and moving everyone over costs more than it gains. Being entrenched is what makes it the practical choice.$batch08$), (2, $batch08$Goal$batch08$, $batch08$A standard already in wide use can be the more practical choice just because it is in wide use.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT133-S3-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$Accuracy is never mentioned. Dvorak is just faster.$batch08$), ($batch08$B$batch08$, $batch08$Qwerty is the standard even though Dvorak is more efficient.$batch08$), ($batch08$C$batch08$, $batch08$The reason is a cost-benefit judgment, not a simple dislike of change. Frustration is one cost among several.$batch08$), ($batch08$D$batch08$, $batch08$The passage adds up time, money, and frustration together. It never weighs emotional cost against money.$batch08$), ($batch08$E$batch08$, $batch08$Switching costs exist only because qwerty is already everywhere, and those costs make it the practical choice.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT133-S3-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
